#!/bin/sh
# Trusted host-net helper. Run only while this agent's client is stopped.
# No provider key/token enters this process. DOCKER-USER also covers bridge peers when br_netfilter is enabled.
set -eu
ACTION=$1
CHAIN=WZPC-$2
INBOUND=WZPI-$2
case "$2" in ''|*[!a-f0-9]*) exit 2 ;; esac
[ "${#CHAIN}" -le 28 ] || exit 2
ipt() { iptables -w 10 "$@"; }
remove_hooks() {
  for base in INPUT DOCKER-USER; do
    ipt -S "$base" | grep -E -- "-j ($CHAIN|$INBOUND)\$" | sed 's/^-A /-D /' | while read -r rule; do
      # Word splitting is intentional: rules are generated by iptables, not provider/user input.
      ipt $rule
    done
  done
}
case "$ACTION" in
  apply)
    SB=$3; RELAY=$4; PROVIDER=$5; PORT=$6; HERMES=$7
    case "$SB $RELAY $PROVIDER $HERMES" in *[!0-9.\ ]*) exit 2 ;; esac
    case "$PORT" in ''|*[!0-9]*) exit 2 ;; esac
    [ "$(cat /proc/sys/net/bridge/bridge-nf-call-iptables)" = 1 ] || { echo 'private client requires br_netfilter' >&2; exit 1; }
    # Docker must already have its forward hook; never invent an unhooked lookalike.
    ipt -C FORWARD -j DOCKER-USER
    ipt -N "$CHAIN" 2>/dev/null || true
    ipt -N "$INBOUND" 2>/dev/null || true
    remove_hooks
    ipt -F "$CHAIN"
    ipt -F "$INBOUND"
    ipt -A "$CHAIN" -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT
    ipt -A "$CHAIN" -d "$PROVIDER" -p tcp --dport "$PORT" -j ACCEPT
    ipt -A "$CHAIN" -j DROP
    ipt -A "$INBOUND" -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT
    ipt -A "$INBOUND" -s "$HERMES" -d "$SB" -p tcp --dport 3301 -j ACCEPT
    ipt -A "$INBOUND" -j DROP
    for source in "$SB" "$RELAY"; do
      ipt -I DOCKER-USER 1 -s "$source/32" -j "$CHAIN"
      ipt -I DOCKER-USER 1 -d "$source/32" -j "$INBOUND"
      # Relay/internal bridges have no host IP, but reject host-address probes explicitly too.
      ipt -I INPUT 1 -s "$source/32" -j "$CHAIN"
    done
    ;;
  remove)
    remove_hooks
    ipt -F "$CHAIN" 2>/dev/null || true
    ipt -X "$CHAIN" 2>/dev/null || true
    ipt -F "$INBOUND" 2>/dev/null || true
    ipt -X "$INBOUND" 2>/dev/null || true
    ;;
  *) exit 2 ;;
esac
